import math

solutions = []
for x in range(1, 6):
    for y in range(1, 6):
        for z in range(1, 6):
            numerator = (x + 1)**y
            denominator = x**z + 1

            # Check if the division results in an integer
            if numerator % denominator == 0:
                solutions.append((x, y, z))

print("Found good triples (x, y, z) in the region 1 <= x, z <= 5 and 1 <= y <= 5:")
for sol in solutions:
    print(sol)

# Also note down the divisibility ratio for pattern spotting (optional but helpful)
print("\nDetailed check:")
for x in range(1, 6):
    for y in range(1, 6):
        for z in range(1, 6):
            numerator = (x + 1)**y
            denominator = x**z + 1

            is_good = numerator % denominator == 0
            if is_good:
                ratio = numerator // denominator
                print(f"({x}, {y}, {z}): Good. Ratio = {ratio}")

